map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/at-cda-imaging-to-fhir-bundle" = "CdaImagingToFhirBundle"

//
// Mapping CDA2FHIR - Befund bildgebende Diagnostik (Diagnostic Imaging Report)
//
// Source: ELGA CDA "Befund bildgebende Diagnostik" https://art-decor.org/ad/#/elgabgd-/rules/templates/1.2.40.0.34.6.0.11.0.17/2024-11-07T13:09:21
//         ClinicalDocument/code/translation = 18748-4 (LOINC)
// Target: HL7 Europe Imaging Report R4 (https://hl7.eu/fhir/imaging/1.0.0-ballot/)
//
// This map holds all imaging-report specific mappings. The generic CDA header (recordTarget,
// author, custodian, legalAuthenticator, ...) and the section framework are reused from
// CdaToFhirBundle.4.map by extending its groups. The data types are reused from
// CdaToFhirTypes.4.map. See python-maps/documentation/imaging/ for the top-level mapping overview.
//
// Naming convention for groups: CdaImaging*ToFhir*
//
// ____________________________________ ConceptMaps ____________________________________

// Translation table: document status in CDA (sdtc:statusCode) -> DiagnosticReport.status
conceptmap "cda-imaging-sdtc-statuscode-2-fhir-diagnosticreport-status" {
  prefix s = "http://terminology.hl7.org/CodeSystem/v3-ActStatus"
  prefix t = "http://hl7.org/fhir/diagnostic-report-status"

  s:"active" == t:"preliminary"
  s:"nullified" == t:"entered-in-error"
}

// ____________________________________ Sources ____________________________________

uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias ClinicalDocument as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias Author as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedAuthor" alias AssignedAuthor as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedEntity" alias AssignedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssociatedEntity" alias AssociatedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/CustodianOrganization" alias CustodianOrganization as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias Section as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/PatientRole" alias PatientRole as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/StructuredBody" alias StructuredBody as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Observation" alias CDAObservation as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/PQ" alias PQ as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/CD" alias CD as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Performer2" alias Performer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Procedure" alias CDAProcedure as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Organizer" alias Organizer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant1" alias Participant as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Act" alias Act as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant2" alias Participant2 as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/ObservationMedia" alias ObservationMedia as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Supply" alias Supply as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Order" alias Order as source

// ____________________________________ Targets ____________________________________

uses "http://hl7.org/fhir/4.3/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Composition" alias Composition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Patient" alias Patient as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Person" alias Person as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Practitioner" alias Practitioner as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/PractitionerRole" alias PractitionerRole as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Organization" alias Organization as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Device" alias Device as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DiagnosticReport" alias DiagnosticReport as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ServiceRequest" alias ServiceRequest as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Observation" alias Observation as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ImagingStudy" alias ImagingStudy as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Procedure" alias Procedure as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Condition" alias Condition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DocumentReference" alias DocumentReference as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DeviceUseStatement" alias DeviceUseStatement as target

// ____________________________________ Imports ____________________________________

imports "http://hl7.at/fhir/HL7ATCoreProfiles/4.0.1/StructureMap/at-cda-to-fhir-types"


// _________________________ Document Level Template _________________________

// Entry point for the imaging report. Called from CdaToFhirBundle when
// ClinicalDocument/code/translation = 18748-4. The Composition and Patient base resources have already
// been created by the root group; here we create the DiagnosticReport and wire the
// base references, then delegate to the header and body groups.
group CdaImagingToFhirBundle(source cda: ClinicalDocument, target fhir_patient: Patient, target fhir_composition: Composition, target fhir_bundle: Bundle) {

  // Bundle.meta.profile
  cda ->
    fhir_bundle.meta as fhir_bundle_meta,
    fhir_bundle_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/BundleReportEuImaging'
    "ImagingBundleProfile";

  cda ->
    // create the DiagnosticReport
    fhir_bundle.entry as fhir_bundle_entry_1,
    fhir_bundle_entry_1.resource = create('DiagnosticReport') as fhir_diagnosticReport,
    fhir_diagnosticReport.id = uuid() as fhir_diagnosticReport_id,
    fhir_bundle_entry_1.fullUrl = append('urn:uuid:', fhir_diagnosticReport_id),

    // retrieve Composition uuid
    fhir_composition.id as fhir_composition_id,

    // DiagnosticReport -> Composition (extension-DiagnosticReport.composition)
    fhir_diagnosticReport.extension as fhir_diagnosticReport_extension,
    fhir_diagnosticReport_extension.url = 'http://hl7.org/fhir/5.0/StructureDefinition/extension-DiagnosticReport.composition',
    fhir_diagnosticReport_extension.value = create('Reference') as fhir_diagnosticReport_composition_reference,
    fhir_diagnosticReport_composition_reference.reference = append('urn:uuid:', fhir_composition_id),
    fhir_diagnosticReport_composition_reference.type = 'Composition',

    // retrieve Patient uuid
    fhir_patient.id as fhir_patient_id,

    // DiagnosticReport -> Patient
    fhir_diagnosticReport.subject = create('Reference') as fhir_diagnosticReport_subject_reference,
    fhir_diagnosticReport_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
    fhir_diagnosticReport_subject_reference.type = 'Patient'

    then {
      // map the CDA header
      cda then CdaImagingHeaderToFhirComposition(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaImagingHeaderToFhirComposition";
      cda then CdaImagingHeaderToFhirDiagnosticReport(cda, fhir_diagnosticReport) "CdaImagingHeaderToFhirDiagnosticReport";
      cda then CdaImagingHeaderToFhir(cda, fhir_composition, fhir_patient, fhir_bundle, fhir_diagnosticReport) "CdaImagingHeaderToFhir";

      // map the CDA body
      // ClinicalDocument.component
      cda.component as cda_component then {
        // ClinicalDocument.component.structuredBody
        cda_component.structuredBody as cda_structuredBody
          then CdaImagingBodyToFhirComposition(cda, cda_structuredBody, fhir_composition, fhir_patient, fhir_diagnosticReport, fhir_bundle);
      };
    } "CdaImagingToFhirBundle";
}


// _________________________ Header Level Templates _________________________

// ClinicalDocument -> Composition (imaging report specific parts).
// Reuses the generic Composition header (title, status, effectiveTime, confidentiality,
// language, setId, versionNumber, ...) from CdaHeaderToFhirComposition.
group CdaImagingHeaderToFhirComposition(source cda: ClinicalDocument, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) extends CdaHeaderToFhirComposition {
    // Composition.meta.profile
    cda ->
        fhir_composition.meta as fhir_composition_meta,
        fhir_composition_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/CompositionEuImaging'
        "ImagingCompositionProfile";

    // ClinicalDocument/code -> Composition.type (same as DiagnosticReport.code)
    cda.code -> fhir_composition.type "ImagingCompositionType";

    // Composition.category (slice imaging-report, fixed value required by the profile)
    // The ELGA category (practiceSettingCode, e.g. Radiologie) is kept in addition.
    cda ->
        fhir_composition.category = create('CodeableConcept') as fhir_composition_category_report,
        fhir_composition_category_report.coding = create('Coding') as fhir_composition_category_report_coding,
        fhir_composition_category_report_coding.system = 'http://loinc.org',
        fhir_composition_category_report_coding.code = '85430-7'
        "ImagingCompositionCategoryReport";

    // Composition.category (slice imaging, fixed value required by the profile)
    cda ->
        fhir_composition.category = create('CodeableConcept') as fhir_composition_category_imaging,
        fhir_composition_category_imaging.coding = create('Coding') as fhir_composition_category_imaging_coding,
        fhir_composition_category_imaging_coding.system = 'http://hl7.eu/fhir/health-data-api/CodeSystem/eehrxf-document-priority-category-cs',
        fhir_composition_category_imaging_coding.code = 'Medical-Imaging'
        "ImagingCompositionCategoryImaging";
}

// ClinicalDocument -> DiagnosticReport.
group CdaImagingHeaderToFhirDiagnosticReport(source cda: ClinicalDocument, target fhir_diagnosticReport: DiagnosticReport) {
    // DiagnosticReport.meta.profile
    cda ->
        fhir_diagnosticReport.meta as fhir_diagnosticReport_meta,
        fhir_diagnosticReport_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/DiagnosticReportEuImaging'
        "ImagingDiagnosticReportProfile";

    // ClinicalDocument/setId -> DiagnosticReport.identifier
    // (profile: identifier common to all versions of the report; same source as Composition.identifier in the ELGA maps)
    cda.setId -> fhir_diagnosticReport.identifier "ImagingDiagnosticReportIdentifier";

    // ClinicalDocument/code -> DiagnosticReport.code
    cda.code -> fhir_diagnosticReport.code "ImagingDiagnosticReportCode";

    // DiagnosticReport.category (slice imaging-report, fixed value required by the profile)
    cda ->
        fhir_diagnosticReport.category = create('CodeableConcept') as fhir_category_report,
        fhir_category_report.coding = create('Coding') as fhir_category_report_coding,
        fhir_category_report_coding.system = 'http://loinc.org',
        fhir_category_report_coding.code = '85430-7'
        "ImagingDiagnosticReportCategoryReport";

    // DiagnosticReport.category (slice imaging, fixed value required by the profile)
    cda ->
        fhir_diagnosticReport.category = create('CodeableConcept') as fhir_category_imaging,
        fhir_category_imaging.coding = create('Coding') as fhir_category_imaging_coding,
        fhir_category_imaging_coding.system = 'http://hl7.eu/fhir/health-data-api/CodeSystem/eehrxf-document-priority-category-cs',
        fhir_category_imaging_coding.code = 'Medical-Imaging'
        "ImagingDiagnosticReportCategoryImaging";

    // ClinicalDocument/sdtc:statusCode -> DiagnosticReport.status (case 1: status present in CDA)
    cda.sdtcStatusCode as cda_statusCode then {
        cda_statusCode.code as cda_status_code ->
            fhir_diagnosticReport.status = translate(cda_status_code, '#cda-imaging-sdtc-statuscode-2-fhir-diagnosticreport-status', 'code')
            "ImagingDiagnosticReportStatusMapped";
    } "ImagingDiagnosticReportStatus";

    // DiagnosticReport.status (case 2: no status in CDA -> report is final)
    cda where cda.sdtcStatusCode.exists().not() ->
        fhir_diagnosticReport.status = 'final'
        "ImagingDiagnosticReportStatusFinal";

    // ClinicalDocument/documentationOf/serviceEvent/effectiveTime -> DiagnosticReport.effectivePeriod
    cda.documentationOf first as cda_documentationOf then {
        cda_documentationOf.serviceEvent as cda_serviceEvent then {
            cda_serviceEvent.effectiveTime as cda_serviceEvent_time ->
                fhir_diagnosticReport.effective = create('Period') as fhir_effective_period
                then IVLTSPeriod(cda_serviceEvent_time, fhir_effective_period)
                "ImagingDiagnosticReportEffective";
        } "ImagingServiceEvent";
    } "ImagingDocumentationOf";

    // ClinicalDocument/effectiveTime -> DiagnosticReport.issued
    cda.effectiveTime -> fhir_diagnosticReport.issued "ImagingDiagnosticReportIssued";
}

// ClinicalDocument -> generic header (recordTarget/Patient, author, custodian,
// legalAuthenticator, ...). Reuses CdaHeaderToFhir; imaging report specific header
// mappings (documentationOf/serviceEvent -> Procedure/ImagingStudy timing,
// inFulfillmentOf/order -> ServiceRequest + AccessionNumber)
// will be added here.
group CdaImagingHeaderToFhir(source cda: ClinicalDocument, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle, target fhir_diagnosticReport: DiagnosticReport) extends CdaHeaderToFhir {
  // TODO ClinicalDocument/documentationOf/serviceEvent -> Procedure / ImagingStudy
  // TODO ClinicalDocument/inFulfillmentOf/order         -> ServiceRequest (basedOn) + AccessionNumber
  // So basically add every header element here that is not covered in `CdaImagingHeaderToFhirDiagnosticReport` or  `CdaImagingHeaderToFhirComposition`
    // Composition.section:procedure (LOINC 55111-9) with all Procedures
    // The section is created here in the header group (not in the body group) because it is
    // mandatory in the EU profile and its entries (Procedures) come from the header (serviceEvent).
    cda where cda.documentationOf.exists() ->
        fhir_composition.section as fhir_section_procedure,
        fhir_section_procedure.code as fhir_section_procedure_code,
        fhir_section_procedure_code.coding as fhir_section_procedure_coding,
        fhir_section_procedure_coding.system = 'http://loinc.org',
        fhir_section_procedure_coding.code = '55111-9'
    then {
        // Title and text from the CDA section "Durchgefuehrte Untersuchung" (55111-9), if present
        cda.component as cda_component then {
            cda_component.structuredBody as cda_structuredBody then {
                cda_structuredBody.component as cda_body_component then {
                    cda_body_component.section as cda_section where (code.where(code = '55111-9' and codeSystem = '2.16.840.1.113883.6.1'))
                        then CdaSectionToFhirSection(cda_section, fhir_section_procedure, fhir_bundle)
                        "ImagingSectionProcedureText";
                    // Komplikationen / complications (LOINC 55109-3) -> subsection of the procedure section.
                    // The EU profile expects complications in the procedure section (slice adverse-event).
                    // The CDA section is narrative only, so no AdverseEvent is derived from the text;
                    // title, text and code are kept as a subsection.
                    cda_body_component.section as cda_section where (code.where(code = '55109-3' and codeSystem = '2.16.840.1.113883.6.1')) ->
                        fhir_section_procedure.section as fhir_section_complications
                        then CdaImagingSectionToFhirSection(cda_section, fhir_section_complications, fhir_bundle)
                        "ImagingSectionComplications";
                } "ImagingBodyComponent";
            } "ImagingStructuredBody";
        } "ImagingComponent";

        // ClinicalDocument/documentationOf/serviceEvent -> Procedure (ProcedureEuImaging)
        // Each examination (serviceEvent) becomes a separate Procedure in the Bundle
        // and is referenced as an entry in the procedure section.
        cda.documentationOf as cda_documentationOf then {
            cda_documentationOf.serviceEvent as cda_serviceEvent ->
                // create the Procedure and add it to the Bundle
                fhir_bundle.entry as fhir_bundle_entry_procedure,
                fhir_bundle_entry_procedure.resource = create('Procedure') as fhir_procedure,
                fhir_procedure.id = uuid() as fhir_procedure_id,
                fhir_bundle_entry_procedure.fullUrl = append('urn:uuid:', fhir_procedure_id),

                // Procedure.meta.profile
                fhir_procedure.meta as fhir_procedure_meta,
                fhir_procedure_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/ProcedureEuImaging',

                // Procedure.status: examination is completed (otherwise there would be no report)
                fhir_procedure.status = 'completed',

                // Procedure -> Patient
                fhir_patient.id as fhir_patient_id,
                fhir_procedure.subject = create('Reference') as fhir_procedure_subject_reference,
                fhir_procedure_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
                fhir_procedure_subject_reference.type = 'Patient',

                // procedure section -> Procedure (entry)
                fhir_section_procedure.entry = create('Reference') as fhir_section_procedure_entry,
                fhir_section_procedure_entry.reference = append('urn:uuid:', fhir_procedure_id),
                fhir_section_procedure_entry.type = 'Procedure'

            then {
                // serviceEvent/code -> Procedure.code
                cda_serviceEvent.code -> fhir_procedure.code "ImagingProcedureCode";

                // serviceEvent/effectiveTime -> Procedure.performedPeriod
                cda_serviceEvent.effectiveTime as cda_serviceEvent_time ->
                    fhir_procedure.performed = create('Period') as fhir_procedure_period
                    then IVLTSPeriod(cda_serviceEvent_time, fhir_procedure_period)
                    "ImagingProcedurePerformed";

                // Radiation dose entries of the procedure section -> Observation, linked to this Procedure.
                // Only if there is exactly one examination; otherwise the dose cannot be assigned to one Procedure.
                cda where (cda.documentationOf.count() = 1)
                    then CdaImagingDoseToFhirObservationLinked(cda, fhir_bundle, fhir_patient, fhir_procedure)
                    "ImagingDoseLinked";
            } "ImagingServiceEventToProcedure";
        } "ImagingDocumentationOfToProcedure";

        // Radiation dose entries if there is more than one examination: Observation without link to a Procedure
        cda where (cda.documentationOf.count() > 1)
            then CdaImagingDoseToFhirObservationUnlinked(cda, fhir_bundle, fhir_patient)
            "ImagingDoseUnlinked";
    } "ImagingSectionProcedure";
}

// _________________________ Header: Order _________________________

// inFulfillmentOf/order (In Fulfillment Of, 1.2.40.0.34.6.0.11.1.9) -> ServiceRequest (ServiceRequestOrderEuImaging).
// order/id is the order number (Auftragsnummer, Leitfaden 3.0.3 S. 111). It is mapped as plain identifier and not as
// Accession Number: according to the ELGA XDS metadata guide, the Accession Number comes from the XDS-I metadata of
// the KOS object, not from the CDA document. For the same reason DiagnosticReport.basedOn is not set (its slice
// requires an Accession Number identifier).
// Note: ServiceRequestOrderEuImaging (1.0.0-ballot) slices identifier by value on 'type' without a fixed value,
// so the validator reports "Slicing cannot be evaluated" for every identifier (profile issue, documented in the thesis).
// Common content of the ServiceRequest (ServiceRequestOrderEuImaging), with or without inFulfillmentOf/order.
// The order number (order/id) is mapped in the calling rule.
group CdaImagingRequestToFhirServiceRequest(source cda: ClinicalDocument, target fhir_serviceRequest: ServiceRequest, target fhir_patient: Patient, target fhir_bundle: Bundle) {
    // the report exists, so the request is fulfilled -> status completed; intent order
    cda ->
        fhir_serviceRequest.status = 'completed',
        fhir_serviceRequest.intent = 'order'
        "ImagingOrderStatusIntent";

    // category required by the EU profile: SNOMED CT 363679005 Imaging (procedure)
    cda ->
        fhir_serviceRequest.category = create('CodeableConcept') as fhir_serviceRequest_category,
        fhir_serviceRequest_category.coding = create('Coding') as fhir_serviceRequest_category_coding,
        fhir_serviceRequest_category_coding.system = 'http://snomed.info/sct',
        fhir_serviceRequest_category_coding.code = '363679005'
        "ImagingOrderCategory";

    // ServiceRequest -> Patient
    cda ->
        fhir_patient.id as fhir_patient_id,
        fhir_serviceRequest.subject = create('Reference') as fhir_serviceRequest_subject,
        fhir_serviceRequest_subject.reference = append('urn:uuid:', fhir_patient_id),
        fhir_serviceRequest_subject.type = 'Patient'
        "ImagingOrderSubject";

    // Zuweiser (participant REF, 1.2.40.0.34.6.0.11.1.21, Leitfaden 3.0.3 S. 107-110) -> ServiceRequest.requester
    // (PractitionerRole with Practitioner and Organization, ELGA group CdaAssociatedEntityToFhirPractitionerRole)
    cda.participant as cda_referrer where (templateId.where(root = '1.2.40.0.34.6.0.11.1.21').exists()) then {
        cda_referrer.associatedEntity as cda_referrer_entity ->
            fhir_bundle.entry as fhir_bundle_entry_referrer,
            fhir_bundle_entry_referrer.resource = create('PractitionerRole') as fhir_practitionerRole,
            fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
            fhir_bundle_entry_referrer.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
            fhir_serviceRequest.requester = create('Reference') as fhir_serviceRequest_requester,
            fhir_serviceRequest_requester.reference = append('urn:uuid:', fhir_practitionerRole_id),
            fhir_serviceRequest_requester.type = 'PractitionerRole'
            then CdaAssociatedEntityToFhirPractitionerRole(cda_referrer_entity, fhir_practitionerRole, fhir_bundle)
            "ImagingOrderRequester";
    } "ImagingOrderReferrer";
}

// _________________________ Section und Entry Level Templates _________________________

// ClinicalDocument body -> Composition sections. Reuses CdaBodyToFhirComposition, which
// already routes the uncoded sections Brieftext (BRIEFT) and Abschliessende Bemerkungen
// to annotation sections. The imaging section dispatch is added here.
group CdaImagingBodyToFhirComposition(source cda: ClinicalDocument, source cda_structuredBody: StructuredBody, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_diagnosticReport: DiagnosticReport, target fhir_bundle: Bundle) extends CdaBodyToFhirComposition {

    // Anforderung / order (LOINC 55115-0) -> Composition.section:order (LOINC 55115-0)
    // The EU profile requires the order section (1..1). It is created if the CDA contains the section
    // Anforderung and/or the section Konsultations- oder Ueberweisungsgrund (LOINC 46239-0).
    // The reason for referral becomes a subsection of the order section.
    cda_structuredBody where (component.section.code.where((code = '55115-0' or code = '46239-0') and codeSystem = '2.16.840.1.113883.6.1').exists()) ->
        fhir_composition.section as fhir_section_order
        then {
            cda_structuredBody.component as cda_order_component then {
                // Anforderung: title, text and code of the order section
                cda_order_component.section as cda_section where (code.where(code = '55115-0' and codeSystem = '2.16.840.1.113883.6.1'))
                    then CdaImagingSectionToFhirSection(cda_section, fhir_section_order, fhir_bundle)
                    "ImagingSectionOrderContent";

                // Konsultations- oder Ueberweisungsgrund (LOINC 46239-0) -> subsection of the order section
                cda_order_component.section as cda_section where (code.where(code = '46239-0' and codeSystem = '2.16.840.1.113883.6.1')) ->
                    fhir_section_order.section as fhir_section_reason
                    then CdaImagingSectionToFhirSection(cda_section, fhir_section_reason, fhir_bundle)
                    "ImagingSectionReason";
            } "ImagingSectionOrderComponents";

            // Without the section Anforderung the order section only gets the EU code (no title or text is invented)
            cda_structuredBody where (component.section.code.where(code = '55115-0' and codeSystem = '2.16.840.1.113883.6.1').exists().not()) ->
                fhir_section_order.code as fhir_order_code,
                fhir_order_code.coding as fhir_order_coding,
                fhir_order_coding.system = 'http://loinc.org',
                fhir_order_coding.code = '55115-0'
                "ImagingSectionOrderCode";

            // inFulfillmentOf/order (Auftrag, Leitfaden 3.0.3 S. 110-111) -> ServiceRequest (ServiceRequestOrderEuImaging),
            // referenced as entry of the order section (Composition.section:order.entry:order); order/id -> identifier
            cda.inFulfillmentOf as cda_fulfillment then {
                cda_fulfillment.order as cda_order ->
                    fhir_bundle.entry as fhir_bundle_entry_order,
                    fhir_bundle_entry_order.resource = create('ServiceRequest') as fhir_serviceRequest,
                    fhir_serviceRequest.id = uuid() as fhir_serviceRequest_id,
                    fhir_bundle_entry_order.fullUrl = append('urn:uuid:', fhir_serviceRequest_id),
                    fhir_section_order.entry = create('Reference') as fhir_section_order_entry,
                    fhir_section_order_entry.reference = append('urn:uuid:', fhir_serviceRequest_id),
                    fhir_section_order_entry.type = 'ServiceRequest'
                    then {
                        cda_order.id as cda_order_id ->
                            fhir_serviceRequest.identifier as fhir_serviceRequest_identifier
                            then II(cda_order_id, fhir_serviceRequest_identifier)
                            "ImagingOrderIdentifier";
                        cda then CdaImagingRequestToFhirServiceRequest(cda, fhir_serviceRequest, fhir_patient, fhir_bundle) "ImagingOrderServiceRequestContent";
                    } "ImagingOrderServiceRequest";
            } "ImagingOrderFulfillment";

            // No inFulfillmentOf, but a referring physician (Zuweiser, participant REF, 1.2.40.0.34.6.0.11.1.21,
            // Leitfaden 3.0.3 S. 107-110): a ServiceRequest without identifier is created so that the referrer
            // is kept as ServiceRequest.requester (decision 24.11.2026).
            cda where (inFulfillmentOf.order.exists().not() and participant.where(templateId.where(root = '1.2.40.0.34.6.0.11.1.21').exists()).exists()) ->
                fhir_bundle.entry as fhir_bundle_entry_request,
                fhir_bundle_entry_request.resource = create('ServiceRequest') as fhir_serviceRequest_ref,
                fhir_serviceRequest_ref.id = uuid() as fhir_serviceRequest_ref_id,
                fhir_bundle_entry_request.fullUrl = append('urn:uuid:', fhir_serviceRequest_ref_id),
                fhir_section_order.entry = create('Reference') as fhir_section_order_entry_ref,
                fhir_section_order_entry_ref.reference = append('urn:uuid:', fhir_serviceRequest_ref_id),
                fhir_section_order_entry_ref.type = 'ServiceRequest'
                then CdaImagingRequestToFhirServiceRequest(cda, fhir_serviceRequest_ref, fhir_patient, fhir_bundle)
                "ImagingReferrerServiceRequest";
        } "ImagingSectionOrder";

    // Imaging study (EU section:imagingstudy, LOINC 18726-0, 1..1, entry:imagingstudy 1..*; BundleReportEuImaging requires an ImagingStudy).
    // An ELGA CDA has no Study Instance UID: the report is linked to the images through the Accession Number in the
    // XDS-I metadata (Leitfaden 3.0.3 S. 19). Following HL7 Europe "Missing Data" (required element without value ->
    // Data Absent Reason) and the recommendation of ELGA GmbH (24.11.2026), an ImagingStudy is created whose
    // Study Instance UID carries the data-absent-reason 'unsupported' (the CDA document cannot carry this value).
    cda_structuredBody ->
        fhir_composition.section as fhir_section_imagingstudy,
        fhir_section_imagingstudy.code = create('CodeableConcept') as fhir_imagingstudy_code,
        fhir_imagingstudy_code.coding = create('Coding') as fhir_imagingstudy_coding,
        fhir_imagingstudy_coding.system = 'http://loinc.org',
        fhir_imagingstudy_coding.code = '18726-0',
        fhir_bundle.entry as fhir_bundle_entry_study,
        fhir_bundle_entry_study.resource = create('ImagingStudy') as fhir_imagingStudy,
        fhir_imagingStudy.id = uuid() as fhir_imagingStudy_id,
        fhir_bundle_entry_study.fullUrl = append('urn:uuid:', fhir_imagingStudy_id),
        fhir_section_imagingstudy.entry = create('Reference') as fhir_section_imagingstudy_entry,
        fhir_section_imagingstudy_entry.reference = append('urn:uuid:', fhir_imagingStudy_id),
        fhir_section_imagingstudy_entry.type = 'ImagingStudy'
        then CdaImagingToFhirImagingStudyPlaceholder(cda, fhir_imagingStudy, fhir_patient)
        "ImagingSectionImagingStudy";

    // Impression (EU section:impression, LOINC 19005-8, max. 1)
    // Case 1: the CDA contains the section Zusammenfassende Beurteilung (LOINC 67781-5). It is the overall
    // assessment of the findings and becomes the impression section (EU code 19005-8 plus the original code).
    // The section Verdachtsdiagnose (LOINC 19005-8) becomes a subsection of it.
    cda_structuredBody where (component.section.code.where(code = '67781-5' and codeSystem = '2.16.840.1.113883.6.1').exists()) ->
        fhir_composition.section as fhir_section_impression,
        fhir_section_impression.code as fhir_impression_code,
        fhir_impression_code.coding as fhir_impression_coding,
        fhir_impression_coding.system = 'http://loinc.org',
        fhir_impression_coding.code = '19005-8'
        then {
            cda_structuredBody.component as cda_impression_component then {
                // Zusammenfassende Beurteilung: title, text and original code of the impression section,
                // coded health problems as Condition entries
                cda_impression_component.section as cda_section where (code.where(code = '67781-5' and codeSystem = '2.16.840.1.113883.6.1')) then {
                    cda_section then CdaImagingSectionToFhirSection(cda_section, fhir_section_impression, fhir_bundle) "ImagingSectionImpressionSummaryContent";

                    // Gesundheitsproblem Bedenken Entry (1.2.40.0.34.11.13.3.6) -> Problem Entry Gesundheitsproblem
                    // (1.2.40.0.34.11.13.3.7) -> Condition (Composition.section:impression.entry:impression), Leitfaden 3.0.3 S. 414-423.
                    // Same structure as Problem Concern Entry / Problem Entry, therefore the same group. Category encounter-diagnosis:
                    // the coded result of the overall assessment of this examination.
                    cda_section.entry as cda_entry then {
                        cda_entry.act as cda_concern where (templateId.where(root = '1.2.40.0.34.11.13.3.6').exists()) then {
                            cda_concern.entryRelationship as cda_concern_relationship where (typeCode = 'SUBJ') then {
                                cda_concern_relationship.observation as cda_problem where (templateId.where(root = '1.2.40.0.34.11.13.3.7').exists()) ->
                                    fhir_bundle.entry as fhir_bundle_entry_condition,
                                    fhir_bundle_entry_condition.resource = create('Condition') as fhir_condition,
                                    fhir_condition.id = uuid() as fhir_condition_id,
                                    fhir_bundle_entry_condition.fullUrl = append('urn:uuid:', fhir_condition_id),
                                    fhir_section_impression.entry = create('Reference') as fhir_section_condition_entry,
                                    fhir_section_condition_entry.reference = append('urn:uuid:', fhir_condition_id),
                                    fhir_section_condition_entry.type = 'Condition',
                                    fhir_condition.category = create('CodeableConcept') as fhir_condition_category,
                                    fhir_condition_category.coding = create('Coding') as fhir_condition_category_coding,
                                    fhir_condition_category_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-category',
                                    fhir_condition_category_coding.code = 'encounter-diagnosis'
                                    then CdaImagingProblemToFhirCondition(cda_concern, cda_problem, fhir_condition, fhir_patient)
                                    "ImagingImpressionCondition";
                            } "ImagingImpressionProblemRelationship";
                        } "ImagingImpressionConcern";
                    } "ImagingImpressionEntry";
                } "ImagingSectionImpressionSummary";

                // Verdachtsdiagnose -> subsection of the impression section
                cda_impression_component.section as cda_section where (code.where(code = '19005-8' and codeSystem = '2.16.840.1.113883.6.1')) ->
                    fhir_section_impression.section as fhir_section_suspected
                    then CdaImagingSectionToFhirSection(cda_section, fhir_section_suspected, fhir_bundle)
                    "ImagingSectionImpressionSuspected";
            } "ImagingSectionImpressionComponents";
        } "ImagingSectionImpressionWithSummary";

    // Case 2: no Zusammenfassende Beurteilung -> Verdachtsdiagnose is the impression section (LOINC 19005-8)
    cda_structuredBody where (component.section.code.where(code = '67781-5' and codeSystem = '2.16.840.1.113883.6.1').exists().not()) then {
        cda_structuredBody.component as cda_impression_component then {
            cda_impression_component.section as cda_section where (code.where(code = '19005-8' and codeSystem = '2.16.840.1.113883.6.1')) ->
                fhir_composition.section as fhir_section_impression
                then CdaImagingSectionToFhirSection(cda_section, fhir_section_impression, fhir_bundle)
                "ImagingSectionImpressionSuspectedOnly";
        } "ImagingSectionImpressionSuspectedComponents";
    } "ImagingSectionImpressionWithoutSummary";

    cda_structuredBody.component as cda_component then {

        // Befund / findings (LOINC 18782-3) -> Composition.section:findings (LOINC 59776-5)
        cda_component.section as cda_section where (code.where(code = '18782-3' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '59776-5'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionFindings";

        // Anamnese / history (LOINC 10164-2) -> Composition.section:history (LOINC 11329-0)
        cda_component.section as cda_section where (code.where(code = '10164-2' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '11329-0'
                        then {
        // title, text, author, code and subsections of the section
        cda_section then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle) "ImagingSectionHistoryContent";

        // Medizinische Geraete und Implantate - kodiert (subsection, LOINC 46264-8):
        // Medical Device Entry (1.2.40.0.34.6.0.11.3.39) -> Device (Composition.section:history.entry:implants)
        // and DeviceUseStatement (implantation date, referenced as further entry of history)
        cda_section.component as cda_history_component then {
            cda_history_component.section as cda_device_section where (code.where(code = '46264-8' and codeSystem = '2.16.840.1.113883.6.1')) then {
                 cda_device_section.entry as cda_device_entry then {
                    cda_device_entry.supply as cda_supply where (templateId.where(root = '1.2.40.0.34.6.0.11.3.39').exists()) ->
                        fhir_bundle.entry as fhir_bundle_entry_device,
                        fhir_bundle_entry_device.resource = create('Device') as fhir_device,
                        fhir_device.id = uuid() as fhir_device_id,
                        fhir_bundle_entry_device.fullUrl = append('urn:uuid:', fhir_device_id),
                        fhir_section.entry = create('Reference') as fhir_section_device_entry,
                        fhir_section_device_entry.reference = append('urn:uuid:', fhir_device_id),
                        fhir_section_device_entry.type = 'Device',
                        fhir_bundle.entry as fhir_bundle_entry_dus,
                        fhir_bundle_entry_dus.resource = create('DeviceUseStatement') as fhir_dus,
                        fhir_dus.id = uuid() as fhir_dus_id,
                        fhir_bundle_entry_dus.fullUrl = append('urn:uuid:', fhir_dus_id),
                        fhir_section.entry = create('Reference') as fhir_section_dus_entry,
                        fhir_section_dus_entry.reference = append('urn:uuid:', fhir_dus_id),
                        fhir_section_dus_entry.type = 'DeviceUseStatement'
                             then CdaImagingMedicalDeviceToFhirDevice(cda_supply, cda_device_section, fhir_device, fhir_dus, fhir_patient)
                                "ImagingHistoryDevice";
                        } "ImagingHistoryDeviceEntry";
                    } "ImagingHistoryDeviceSection";
                } "ImagingHistoryDeviceComponent";

        // Fruehere Erkrankungen und Massnahmen - kodiert (subsection, LOINC 11348-0, 1.2.40.0.34.6.0.11.2.74,
        // Leitfaden 3.0.3 S. 163-167): Problem Concern Entry (1.2.40.0.34.6.0.11.3.7) -> Problem Entry
        // (1.2.40.0.34.6.0.11.3.6) -> Condition (Composition.section:history.entry:problemlist).
        // Category problem-list-item: earlier diseases, not a diagnosis of this examination.
        cda_section.component as cda_history_component then {
            cda_history_component.section as cda_problem_section where (code.where(code = '11348-0' and codeSystem = '2.16.840.1.113883.6.1')) then {
                cda_problem_section.entry as cda_problem_entry then {
                    cda_problem_entry.act as cda_concern where (templateId.where(root = '1.2.40.0.34.6.0.11.3.7').exists()) then {
                        cda_concern.entryRelationship as cda_concern_relationship where (typeCode = 'SUBJ') then {
                            cda_concern_relationship.observation as cda_problem where (templateId.where(root = '1.2.40.0.34.6.0.11.3.6').exists()) ->
                                fhir_bundle.entry as fhir_bundle_entry_condition,
                                fhir_bundle_entry_condition.resource = create('Condition') as fhir_condition,
                                fhir_condition.id = uuid() as fhir_condition_id,
                                fhir_bundle_entry_condition.fullUrl = append('urn:uuid:', fhir_condition_id),
                                fhir_section.entry = create('Reference') as fhir_section_condition_entry,
                                fhir_section_condition_entry.reference = append('urn:uuid:', fhir_condition_id),
                                fhir_section_condition_entry.type = 'Condition',
                                fhir_condition.category = create('CodeableConcept') as fhir_condition_category,
                                fhir_condition_category.coding = create('Coding') as fhir_condition_category_coding,
                                fhir_condition_category_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-category',
                                fhir_condition_category_coding.code = 'problem-list-item'
                                then CdaImagingProblemToFhirCondition(cda_concern, cda_problem, fhir_condition, fhir_patient)
                                "ImagingHistoryCondition";
                        } "ImagingHistoryProblemRelationship";
                    } "ImagingHistoryConcern";
                } "ImagingHistoryProblemEntry";
            } "ImagingHistoryProblemSection";
        } "ImagingHistoryProblemComponent";
        } "ImagingSectionHistory";

        // Fruehere Untersuchungen und Befunde / prior examinations (LOINC 55114-3) -> Composition.section:comparison (LOINC 18834-2)
        cda_component.section as cda_section where (code.where(code = '55114-3' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '18834-2'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionComparison";

        // Weitere empfohlene Massnahmen / recommended actions (LOINC 59772-4) -> Composition.section:recommendation (LOINC 18783-1)
        cda_component.section as cda_section where (code.where(code = '59772-4' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '18783-1'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionRecommendation";

        // Sections without an EU slice: added as own sections with their original code, title and text
        // (the section slicing of CompositionEuImaging is open). Subsections are kept via the recursion
        // in CdaImagingSectionToFhirSection.

        // Status, Diagnostik und Befunde / clinical status and findings (SNOMED CT 424836000) -> own section.
        // Clinical findings of the current consultation, not imaging findings, therefore not in section:findings.
        cda_component.section as cda_section where (code.where(code = '424836000' and codeSystem = '2.16.840.1.113883.6.96')) ->
            fhir_composition.section as fhir_section
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionClinicalStatus";

        // Diagnose / diagnosis (SNOMED CT 439401001) -> own section (title, text) with the coded diagnoses as Condition entries.
        cda_component.section as cda_section where (code.where(code = '439401001' and codeSystem = '2.16.840.1.113883.6.96')) ->
            fhir_composition.section as fhir_section
            then {
                // title, text, author and code of the section
                cda_section then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle) "ImagingSectionDiagnosisContent";

                // Problem Concern Entry (1.2.40.0.34.6.0.11.3.7) -> Problem Entry (1.2.40.0.34.6.0.11.3.6) -> Condition,
                // referenced as entry of the diagnosis section
                cda_section.entry as cda_entry then {
                    cda_entry.act as cda_concern where (templateId.where(root = '1.2.40.0.34.6.0.11.3.7').exists()) then {
                        cda_concern.entryRelationship as cda_concern_relationship where (typeCode = 'SUBJ') then {
                            cda_concern_relationship.observation as cda_problem where (templateId.where(root = '1.2.40.0.34.6.0.11.3.6').exists()) ->
                                fhir_bundle.entry as fhir_bundle_entry_condition,
                                fhir_bundle_entry_condition.resource = create('Condition') as fhir_condition,
                                fhir_condition.id = uuid() as fhir_condition_id,
                                fhir_bundle_entry_condition.fullUrl = append('urn:uuid:', fhir_condition_id),

                                // diagnosis section -> Condition (entry)
                                fhir_section.entry = create('Reference') as fhir_section_condition_entry,
                                fhir_section_condition_entry.reference = append('urn:uuid:', fhir_condition_id),
                                fhir_section_condition_entry.type = 'Condition',
                                // Condition.category: diagnosis made in the context of this examination
                                fhir_condition.category = create('CodeableConcept') as fhir_condition_category,
                                fhir_condition_category.coding = create('Coding') as fhir_condition_category_coding,
                                fhir_condition_category_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-category',
                                fhir_condition_category_coding.code = 'encounter-diagnosis'
                                then CdaImagingProblemToFhirCondition(cda_concern, cda_problem, fhir_condition, fhir_patient)
                                "ImagingDiagnosisCondition";
                        } "ImagingDiagnosisProblemRelationship";
                    } "ImagingDiagnosisConcern";
                } "ImagingDiagnosisEntry";
            } "ImagingSectionDiagnosis";
        // Beilagen / attachments (ELGA_Sections BEIL): Eingebettetes Objekt Entry (1.2.40.0.34.6.0.11.3.19)
        // -> DocumentReference, linked from DiagnosticReport.media.link via the extension alternate-reference,
        // as in the HL7 EU Laboratory DiagnosticReport and MyHealth@EU LRR (ELGA GmbH, 23.11.2026).
        // DiagnosticReportEuImaging still only allows Reference(Media) in media.link; ELGA GmbH raises this with HL7 Europe.
        // Only the author is mapped (observationMedia author and section author -> DocumentReference.author);
        // participant, performer and informant are left out (ELGA GmbH, 23.11.2026).
        cda_component.section as cda_section where (code.where(code = 'BEIL' and codeSystem = '1.2.40.0.34.5.40')) then {
            cda_section.entry as cda_entry then {
                cda_entry.observationMedia as cda_observationMedia where (templateId.where(root = '1.2.40.0.34.6.0.11.3.19').exists()) ->
                    fhir_bundle.entry as fhir_bundle_entry_docref,
                    fhir_bundle_entry_docref.resource = create('DocumentReference') as fhir_documentReference,
                    fhir_documentReference.id = uuid() as fhir_documentReference_id,
                    fhir_bundle_entry_docref.fullUrl = append('urn:uuid:', fhir_documentReference_id),

                    // link.reference is not used, link.display is mandatory in the EU Lab profile,
                    // the pointer to the DocumentReference goes through the extension alternate-reference
                    fhir_diagnosticReport.media as fhir_diagnosticReport_media,
                    fhir_diagnosticReport_media.link = create('Reference') as fhir_diagnosticReport_media_link,
                    fhir_diagnosticReport_media_link.display = 'Instead of a reference to a Media resource, a DocumentReference resource is linked through the cross-version extension \'link\'.',
                    fhir_diagnosticReport_media_link.extension as fhir_diagnosticReport_media_link_extension,
                    fhir_diagnosticReport_media_link_extension.url = 'http://hl7.org/fhir/StructureDefinition/alternate-reference',
                    fhir_diagnosticReport_media_link_extension.value = create('Reference') as fhir_diagnosticReport_media_link_extension_reference,
                    fhir_diagnosticReport_media_link_extension_reference.reference = append('urn:uuid:', fhir_documentReference_id),
                    fhir_diagnosticReport_media_link_extension_reference.type = 'DocumentReference'
                    then {
                        cda_observationMedia then CdaObservationMediaToFhirDocumentReference(cda_observationMedia, fhir_documentReference, fhir_patient, fhir_bundle) "ImagingAttachmentDocumentReference";

                        // author of the Beilagen section -> DocumentReference.author (PractitionerRole, as in CdaSectionToFhirSection)
                        cda_section.author as cda_section_author ->
                            fhir_bundle.entry as fhir_bundle_entry_author,
                            fhir_bundle_entry_author.resource = create('PractitionerRole') as fhir_practitionerRole,
                            fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
                            fhir_bundle_entry_author.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
                            fhir_documentReference.author = create('Reference') as fhir_documentReference_author,
                            fhir_documentReference_author.reference = append('urn:uuid:', fhir_practitionerRole_id),
                            fhir_documentReference_author.type = 'PractitionerRole'
                            then CdaAuthorToFhirPractitionerRole(cda_section_author, fhir_practitionerRole, fhir_bundle)
                            "ImagingAttachmentSectionAuthor";
                    } "ImagingAttachmentDocumentReferenceLinked";
            } "ImagingAttachmentEntry";
        } "ImagingSectionAttachments";
    } "ImagingSections";
}

// Common rules for every imaging section.
// Reuses title, text and author from CdaSectionToFhirSection (ELGA) and
// adds the original code of the CDA section.
group CdaImagingSectionToFhirSection(source cda_section: Section, target fhir_section, target fhir_bundle: Bundle) extends CdaSectionToFhirSection {
    // section/code -> Composition.section.code
    // (as an additional coding, so that an EU code set before is kept)
    cda_section.code as cda_section_code ->
        fhir_section.code as fhir_section_code,
        fhir_section_code.coding as fhir_section_coding
        then CDCoding(cda_section_code, fhir_section_coding)
        "ImagingSectionCode";

    // Subsections: section/component/section -> Composition.section.section
    // (calls this group again for every subsection)
    cda_section.component as cda_sub_component then {
        cda_sub_component.section as cda_sub_section ->
            fhir_section.section as fhir_sub_section
            then CdaImagingSectionToFhirSection(cda_sub_section, fhir_sub_section, fhir_bundle)
            "ImagingSubSection";
    } "ImagingSubSections";
} 

// _________________________ Imaging Study (placeholder) _________________________

// ImagingStudy for the section imagingstudy when the CDA has no Study Instance UID (see rule ImagingSectionImagingStudy).
// identifier:studyInstanceUid (StudyInstanceUidIdentifierEuImaging): type DCM 110180, system urn:dicom:uid,
// value 1..1 -> data-absent-reason 'unsupported'. status 'unknown': the CDA says nothing about the state of the study.
group CdaImagingToFhirImagingStudyPlaceholder(source cda: ClinicalDocument, target fhir_imagingStudy: ImagingStudy, target fhir_patient: Patient) {
    cda ->
        fhir_imagingStudy.status = 'unknown'
        "ImagingStudyStatus";

    cda ->
        fhir_patient.id as fhir_patient_id,
        fhir_imagingStudy.subject = create('Reference') as fhir_imagingStudy_subject,
        fhir_imagingStudy_subject.reference = append('urn:uuid:', fhir_patient_id),
        fhir_imagingStudy_subject.type = 'Patient'
        "ImagingStudySubject";

    cda ->
        fhir_imagingStudy.identifier as fhir_study_identifier,
        fhir_study_identifier.type = create('CodeableConcept') as fhir_study_identifier_type,
        fhir_study_identifier_type.coding = create('Coding') as fhir_study_identifier_type_coding,
        fhir_study_identifier_type_coding.system = 'http://dicom.nema.org/resources/ontology/DCM',
        fhir_study_identifier_type_coding.code = '110180',
        fhir_study_identifier_type_coding.display = 'Study Instance UID',
        fhir_study_identifier.system = 'urn:dicom:uid',
        fhir_study_identifier.value as fhir_study_identifier_value,
        fhir_study_identifier_value.extension as fhir_study_identifier_value_extension,
        fhir_study_identifier_value_extension.url = 'http://hl7.org/fhir/StructureDefinition/data-absent-reason',
        fhir_study_identifier_value_extension.value = create('code') as fhir_study_identifier_value_code,
        fhir_study_identifier_value_code.value = 'unsupported'
        "ImagingStudyInstanceUidAbsent";
}

// _________________________ Entry Level Templates: Radiation Dose _________________________

// Radiation dose (templateId 1.2.40.0.34.6.0.11.3.183, e.g. DCM 113813 CT Dose Length Product Total)
// in the section "Durchgefuehrte Untersuchung" (55111-9) -> Observation.
// Not mapped to ObservationRadiationDoseEuImaging: that profile requires partOf:study (ImagingStudy, 1..1),
// which cannot be created from a v3 report (no Study Instance UID), and allows the value only as a
// string (LOINC 73569-6). A plain Observation keeps the coded quantity (value and unit) without loss.
// The Observation is not added as an entry of the procedure section: the slices of that section only
// accept ProcedureEuImaging, AdverseEventEuImaging and ObservationRadiationDoseEuImaging.
// It is linked to the examination via Observation.partOf instead.

// Case 1: exactly one examination -> Observation.partOf references the Procedure
group CdaImagingDoseToFhirObservationLinked(source cda: ClinicalDocument, target fhir_bundle: Bundle, target fhir_patient: Patient, target fhir_procedure: Procedure) {
    cda.component as cda_component then {
        cda_component.structuredBody as cda_structuredBody then {
            cda_structuredBody.component as cda_body_component then {
                cda_body_component.section as cda_section where (code.where(code = '55111-9' and codeSystem = '2.16.840.1.113883.6.1')) then {
                    cda_section.entry as cda_entry then {
                        cda_entry.observation as cda_observation where (templateId.where(root = '1.2.40.0.34.6.0.11.3.183').exists()) ->
                            fhir_bundle.entry as fhir_bundle_entry_dose,
                            fhir_bundle_entry_dose.resource = create('Observation') as fhir_observation,
                            fhir_observation.id = uuid() as fhir_observation_id,
                            fhir_bundle_entry_dose.fullUrl = append('urn:uuid:', fhir_observation_id),

                            // Observation -> Procedure (partOf)
                            fhir_procedure.id as fhir_procedure_id,
                            fhir_observation.partOf = create('Reference') as fhir_observation_partof,
                            fhir_observation_partof.reference = append('urn:uuid:', fhir_procedure_id),
                            fhir_observation_partof.type = 'Procedure'
                            then CdaImagingDoseObservationToFhirObservation(cda_observation, fhir_observation, fhir_patient)
                            "ImagingDoseObservationLinked";
                    } "ImagingDoseEntryLinked";
                } "ImagingDoseSectionLinked";
            } "ImagingDoseBodyComponentLinked";
        } "ImagingDoseStructuredBodyLinked";
    } "ImagingDoseComponentLinked";
}

// Case 2: more than one examination -> Observation without partOf
group CdaImagingDoseToFhirObservationUnlinked(source cda: ClinicalDocument, target fhir_bundle: Bundle, target fhir_patient: Patient) {
    cda.component as cda_component then {
        cda_component.structuredBody as cda_structuredBody then {
            cda_structuredBody.component as cda_body_component then {
                cda_body_component.section as cda_section where (code.where(code = '55111-9' and codeSystem = '2.16.840.1.113883.6.1')) then {
                    cda_section.entry as cda_entry then {
                        cda_entry.observation as cda_observation where (templateId.where(root = '1.2.40.0.34.6.0.11.3.183').exists()) ->
                            fhir_bundle.entry as fhir_bundle_entry_dose,
                            fhir_bundle_entry_dose.resource = create('Observation') as fhir_observation,
                            fhir_observation.id = uuid() as fhir_observation_id,
                            fhir_bundle_entry_dose.fullUrl = append('urn:uuid:', fhir_observation_id)
                            then CdaImagingDoseObservationToFhirObservation(cda_observation, fhir_observation, fhir_patient)
                            "ImagingDoseObservationUnlinked";
                    } "ImagingDoseEntryUnlinked";
                } "ImagingDoseSectionUnlinked";
            } "ImagingDoseBodyComponentUnlinked";
        } "ImagingDoseStructuredBodyUnlinked";
    } "ImagingDoseComponentUnlinked";
}

// Common content of a radiation dose Observation
group CdaImagingDoseObservationToFhirObservation(source cda_observation: CDAObservation, target fhir_observation: Observation, target fhir_patient: Patient) {
    // observation/statusCode (fixed value completed) -> Observation.status
    cda_observation.statusCode as cda_status where (code = 'completed') ->
        fhir_observation.status = 'final'
        "ImagingDoseStatus";

    // Observation.category: imaging
    cda_observation ->
        fhir_observation.category = create('CodeableConcept') as fhir_dose_category,
        fhir_dose_category.coding = create('Coding') as fhir_dose_category_coding,
        fhir_dose_category_coding.system = 'http://terminology.hl7.org/CodeSystem/observation-category',
        fhir_dose_category_coding.code = 'imaging'
        "ImagingDoseCategory";

    // observation/code (DCM, e.g. 113813) -> Observation.code
    cda_observation.code as cda_code ->
        fhir_observation.code = create('CodeableConcept') as fhir_dose_code
        then CDCodeableConcept(cda_code, fhir_dose_code)
        "ImagingDoseCode";

    // Observation -> Patient
    cda_observation ->
        fhir_patient.id as fhir_patient_id,
        fhir_observation.subject = create('Reference') as fhir_dose_subject,
        fhir_dose_subject.reference = append('urn:uuid:', fhir_patient_id),
        fhir_dose_subject.type = 'Patient'
        "ImagingDoseSubject";

    // observation/effectiveTime -> Observation.effectiveDateTime
    cda_observation.effectiveTime as cda_effectiveTime ->
        fhir_observation.effective = create('dateTime') as fhir_dose_effective
        then TSDateTime(cda_effectiveTime, fhir_dose_effective)
        "ImagingDoseEffective";

    // observation/value (PQ, e.g. 230 mGy.cm) -> Observation.valueQuantity (UCUM)
    cda_observation.value : PQ as cda_value ->
        fhir_observation.value = create('Quantity') as fhir_dose_value
        then PQQuantity(cda_value, fhir_dose_value)
        "ImagingDoseValue";
}


// _________________________ Entry Level Templates: Diagnosis _________________________

// Problem Concern Entry (cda_concern) + Problem Entry (cda_problem) -> Condition.
// Leitfaden 3.0.3, 14.3.3.12.1 and 14.3.3.12.1.1:
// - The status of the concern (act/statusCode) is NOT the status of the disease itself, therefore it is
//   not mapped to Condition.clinicalStatus.
// - Problem effectiveTime/low = onset, effectiveTime/high = end of the problem. Without high the problem
//   is still existing -> clinicalStatus active; with high -> resolved.
// - Concern effectiveTime/low = the problem was documented for the first time -> recordedDate.
// Not mapped: value/qualifier (type of diagnosis, e.g. 8319008 principal diagnosis). FHIR R4 Condition has
// no element for it (rank only exists in Encounter.diagnosis); documented as limitation in the mapping overview.
group CdaImagingProblemToFhirCondition(source cda_concern: Act, source cda_problem: CDAObservation, target fhir_condition: Condition, target fhir_patient: Patient) {
    // Problem Entry/id -> Condition.identifier
    cda_problem.id -> fhir_condition.identifier "ImagingConditionIdentifier";

    // Condition.category is set in the calling rule: encounter-diagnosis (section Diagnose)
    // or problem-list-item (earlier diseases in the section Anamnese)

    // Problem Entry/value (the diagnosis, e.g. SNOMED CT 400210000 Haemangioma) -> Condition.code
    cda_problem.value : CD as cda_problem_value ->
        fhir_condition.code = create('CodeableConcept') as fhir_condition_code
        then CDCodeableConcept(cda_problem_value, fhir_condition_code)
        "ImagingConditionCode";

    // Condition -> Patient
    cda_problem ->
        fhir_patient.id as fhir_patient_id,
        fhir_condition.subject = create('Reference') as fhir_condition_subject,
        fhir_condition_subject.reference = append('urn:uuid:', fhir_patient_id),
        fhir_condition_subject.type = 'Patient'
        "ImagingConditionSubject";

    // Problem Entry/effectiveTime -> Condition.onsetDateTime / abatementDateTime
    cda_problem.effectiveTime as cda_problem_time then {
        cda_problem_time.low as cda_problem_low where (nullFlavor.exists().not()) ->
            fhir_condition.onset = create('dateTime') as fhir_condition_onset
            then IVXB_TSDateTime(cda_problem_low, fhir_condition_onset)
            "ImagingConditionOnset";
        cda_problem_time.high as cda_problem_high where (nullFlavor.exists().not()) ->
            fhir_condition.abatement = create('dateTime') as fhir_condition_abatement
            then IVXB_TSDateTime(cda_problem_high, fhir_condition_abatement)
            "ImagingConditionAbatement";
    } "ImagingConditionEffectiveTime";

    // Condition.clinicalStatus: no effectiveTime/high -> active
    cda_problem where (effectiveTime.high.exists().not()) ->
        fhir_condition.clinicalStatus = create('CodeableConcept') as fhir_condition_clinical,
        fhir_condition_clinical.coding = create('Coding') as fhir_condition_clinical_coding,
        fhir_condition_clinical_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-clinical',
        fhir_condition_clinical_coding.code = 'active'
        "ImagingConditionClinicalStatusActive";

    // Condition.clinicalStatus: effectiveTime/high present -> resolved
    cda_problem where (effectiveTime.high.exists()) ->
        fhir_condition.clinicalStatus = create('CodeableConcept') as fhir_condition_clinical,
        fhir_condition_clinical.coding = create('Coding') as fhir_condition_clinical_coding,
        fhir_condition_clinical_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-clinical',
        fhir_condition_clinical_coding.code = 'resolved'
        "ImagingConditionClinicalStatusResolved";

    // negationInd = true: the diagnosis was ruled out -> verificationStatus refuted
    cda_problem where (negationInd = true) ->
        fhir_condition.verificationStatus = create('CodeableConcept') as fhir_condition_verification,
        fhir_condition_verification.coding = create('Coding') as fhir_condition_verification_coding,
        fhir_condition_verification_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-ver-status',
        fhir_condition_verification_coding.code = 'refuted'
        "ImagingConditionRefuted";

    // Problem Concern Entry/effectiveTime/low (first documented) -> Condition.recordedDate
    cda_concern.effectiveTime as cda_concern_time then {
        cda_concern_time.low as cda_concern_low where (nullFlavor.exists().not()) ->
            fhir_condition.recordedDate as fhir_condition_recorded
            then IVXB_TSDateTime(cda_concern_low, fhir_condition_recorded)
            "ImagingConditionRecordedDate";
    } "ImagingConditionConcernTime";
}
// _________________________ Entry Level Templates: Attachments _________________________

// Eingebettetes Objekt Entry (1.2.40.0.34.6.0.11.3.19), e.g. a PDF in the section Beilagen -> DocumentReference.
// Taken over from CdaLabToFhirBundle.4.map (HL7Austria/CDA2FHIR PR#237, branch myhealtheu-dev),
// as recommended by ELGA GmbH (23.11.2026). Added: observationMedia/author -> DocumentReference.author.
// If PR#237 is merged into this branch, this copy has to be removed (same group name).
group CdaObservationMediaToFhirDocumentReference(source cda_observationMedia : ObservationMedia, target fhir_documentReference : DocumentReference, target fhir_patient : Patient, target fhir_bundle : Bundle){

  cda_observationMedia.id -> fhir_documentReference.identifier;

  cda_observationMedia -> fhir_documentReference.status = 'current';

  cda_observationMedia ->
    fhir_documentReference.subject = create('Reference') as fhir_documentReference_subject_reference,
    fhir_patient.id as fhir_patient_id,
    fhir_documentReference_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
    fhir_documentReference_subject_reference.type = 'Patient'
    "FhirDocumentReferenceSubject";

  cda_observationMedia.value as cda_observationMedia_value ->
    fhir_documentReference.content as fhir_documentReference_content,
    fhir_documentReference_content.attachment = create('Attachment') as fhir_documentReference_attachment then {

      // cda_observationMedia.value@mediaType
      cda_observationMedia_value.mediaType as cda_mediaType -> fhir_documentReference_attachment.contentType = cda_mediaType;
      // cda_observationMedia.value
      cda_observationMedia_value -> fhir_documentReference_attachment.data = (cda_observationMedia_value.xmlText) "CdaObservationMediaValueToFhirAttachmentData";
    };

  // observationMedia.author -> DocumentReference.author (PractitionerRole, as for the section author in CdaSectionToFhirSection)
  cda_observationMedia.author as cda_observationMedia_author ->
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('PractitionerRole') as fhir_practitionerRole,
    fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_documentReference.author = create('Reference') as fhir_documentReference_author_reference,
    fhir_documentReference_author_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_documentReference_author_reference.type = 'PractitionerRole'
    then CdaAuthorToFhirPractitionerRole(cda_observationMedia_author, fhir_practitionerRole, fhir_bundle)
    "CdaObservationMediaAuthorToFhirDocumentReferenceAuthor";

  // Not mapped (ELGA GmbH, 23.11.2026, Mapping Methodology "Prioritize the agreed core data set and leave out
  // what is hard and of dubious use"): observationMedia.performer, .informant and .participant.
}
// _________________________ Entry Level Templates: Medical Device _________________________

// Medical Device Entry (1.2.40.0.34.6.0.11.3.39, adaptation of IPS Medical Device) in the subsection
// "Medizinische Geraete und Implantate - kodiert" -> Device + DeviceUseStatement (as in the IPS).
// Leitfaden 3.0.3, 14.3.3.5.7.1: effectiveTime/low = date of supply/implantation, no high (only devices in current use);
// participantRole/id = serial number or UDI; playingDevice/code = type of device, or nullFlavor with
// originalText/reference to the narrative if no code is possible.
group CdaImagingMedicalDeviceToFhirDevice(source cda_supply: Supply, source cda_section: Section, target fhir_device: Device, target fhir_dus: DeviceUseStatement, target fhir_patient: Patient) {
    // Device.status: the device is in current use
    cda_supply -> fhir_device.status = 'active' "ImagingDeviceStatus";

    // Device -> Patient
    cda_supply ->
        fhir_patient.id as fhir_patient_id,
        fhir_device.patient = create('Reference') as fhir_device_patient,
        fhir_device_patient.reference = append('urn:uuid:', fhir_patient_id),
        fhir_device_patient.type = 'Patient'
        "ImagingDevicePatient";

    cda_supply.participant as cda_participant where (typeCode = 'DEV') then {
        cda_participant.participantRole as cda_role then {
            // participantRole/id (serial number, UDI) -> Device.identifier
            cda_role.id as cda_role_id where (nullFlavor.exists().not()) ->
                fhir_device.identifier as fhir_device_identifier
                then II(cda_role_id, fhir_device_identifier)
                "ImagingDeviceIdentifier";

            cda_role.playingDevice as cda_playing_device then {
                // coded device -> Device.type
                cda_playing_device.code as cda_device_code where (nullFlavor.exists().not()) ->
                    fhir_device.type = create('CodeableConcept') as fhir_device_type
                    then CECodeableConcept(cda_device_code, fhir_device_type)
                    "ImagingDeviceTypeCoded";

                // uncoded device: code/originalText/reference -> Device.type.text (text of the referenced narrative element)
                cda_playing_device.code as cda_device_code where (nullFlavor.exists()) then {
                    cda_device_code.originalText as cda_original_text then {
                        cda_original_text.reference as cda_original_reference then {
                            cda_section.text as cda_section_text then {
                                cda_original_reference.value as cda_reference_value ->
                                    create('Narrative') as fhir_narrative,
                                    fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                    create('string') as fhir_string,
                                    fhir_string = (fhir_narrative_div),
                                    create('string') as fhir_substring_01,
                                    fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_reference_value.substring(1)))),
                                    create('string') as fhir_substring_02,
                                    fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),
                                    fhir_device.type = create('CodeableConcept') as fhir_device_type,
                                    fhir_device_type.text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')).replaceMatches('^\\s+|\\s+$', ''))
                                    "ImagingDeviceTypeText";
                            } "ImagingDeviceSectionText";
                        } "ImagingDeviceOriginalReference";
                    } "ImagingDeviceOriginalText";
                } "ImagingDeviceTypeUncoded";
            } "ImagingDevicePlayingDevice";
        } "ImagingDeviceParticipantRole";
    } "ImagingDeviceParticipant";

    // DeviceUseStatement: status, subject, device
    cda_supply -> fhir_dus.status = 'active' "ImagingDeviceUseStatus";
    cda_supply ->
        fhir_patient.id as fhir_patient_id,
        fhir_dus.subject = create('Reference') as fhir_dus_subject,
        fhir_dus_subject.reference = append('urn:uuid:', fhir_patient_id),
        fhir_dus_subject.type = 'Patient'
        "ImagingDeviceUseSubject";
    cda_supply ->
        fhir_device.id as fhir_device_id,
        fhir_dus.device = create('Reference') as fhir_dus_device,
        fhir_dus_device.reference = append('urn:uuid:', fhir_device_id),
        fhir_dus_device.type = 'Device'
        "ImagingDeviceUseDevice";

    // effectiveTime/low (date of implantation) -> DeviceUseStatement.timingDateTime
    cda_supply.effectiveTime as cda_supply_time then {
        cda_supply_time.low as cda_supply_low where (nullFlavor.exists().not()) ->
            fhir_dus.timing = create('dateTime') as fhir_dus_timing
            then IVXB_TSDateTime(cda_supply_low, fhir_dus_timing)
            "ImagingDeviceUseTiming";
    } "ImagingDeviceUseTime";
}
